<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:Arial,sans-serif;max-width:900px;margin:2rem auto;padding:1rem;color:#111}.top,.line,.totals div{display:flex;justify-content:space-between;gap:1rem}.line{border-bottom:1px solid #ddd;padding:.75rem 0}.totals{margin:1.5rem 0 0 auto;max-width:360px}.grand{font-size:1.3rem;font-weight:bold}.print{margin:1rem 0}@media print{.print{display:none}body{margin:0;max-width:none}}@media(max-width:500px){.top,.line{display:block}.line span{display:block;margin-top:.25rem}}</style></head><body><button class="print" onclick="window.print()">Print / Save as PDF</button><div class="top"><div><h1>Customer Invoice</h1><p>Company identity</p></div><div><strong>{{ $invoice->invoice_number }}</strong><p>Order {{ $invoice->order_number_snapshot }}</p><p>{{ ($invoice->issued_at ?? $invoice->created_at)->format('Y-m-d H:i') }}</p></div></div><hr><p><strong>{{ $invoice->customer_name_snapshot }}</strong><br>{{ $invoice->customer_phone_snapshot }}<br>{{ $invoice->area_snapshot }}<br>{{ $invoice->address_snapshot }}</p><h2>Items</h2>@foreach($invoice->items as $item)<div class="line"><span>{{ $item->description }} · {{ $item->quantity }} {{ $item->unit_name_snapshot }}</span><span>{{ $item->unit_price }} × {{ $item->quantity }}</span><strong>{{ $item->line_total }} {{ $invoice->currency->code }}</strong></div>@endforeach<div class="totals"><div><span>Items subtotal</span><span>{{ $invoice->items_subtotal }}</span></div><div><span>Delivery</span><span>{{ $invoice->delivery_total }}</span></div><div class="grand"><span>Grand total</span><span>{{ $invoice->grand_total }} {{ $invoice->currency->code }}</span></div></div><p>This browser-ready document can be printed, saved as PDF, and sent manually through WhatsApp.</p></body></html>
